for k1, v1 in tbl3.Items, nil do
	v1.Id = k1
end

tbl3.Get = function(arg1)
	if typeof(arg1) ~= "string" then
		return nil
	end

	return tbl3.Items[arg1]
end

tbl3.GetByCategory = function(arg1)
	local tbl1 = {}
	for k1, v1 in tbl3.Items, nil do
		if v1.Category ~= arg1 then
			continue
		end

		table.insert(tbl1, v1)
	end

	table.sort(tbl1, function(arg1, arg2)
		local var3 = tbl3.Rarities[arg1.Rarity].Order
		local var4 = tbl3.Rarities[arg2.Rarity].Order
		if var3 ~= var4 then
			return var3 < var4
		end

		if arg1.Tier ~= arg2.Tier then
			return arg1.Tier < arg2.Tier
		end

		return arg1.Id < arg2.Id
	end)

	return tbl1
end

tbl3.GetModel = function(arg1)
	local var3 = tbl3.Get(arg1)
	if not var3 then
		return nil
	end

	local var4 = if not var2:IsServer() and var2:IsRunning() then nil else game:GetService("ServerStorage"):FindFirstChild("Items")
	local var5 = var4
	var5 = var5 and var4:FindFirstChild(var3.Category)
	local var6 = var5
	var6 = var6 and var5:FindFirstChild(var3.ModelName)
	if var6 and var6:IsA("Model") then
		return var6
	end

	return nil
end

tbl3.GetPlacementShape = function(arg1, arg2)
	local var2 = tbl3.Get(arg1)
	local var3 = arg2
	var3 = var3 or tbl3.GetModel(arg1)
	local var4 = var3
	var4 = var4 and (var3:IsA("Model") and var3:FindFirstChild("PlacementBase"))
	local var6 = if var2 and typeof(var2.Footprint) == "Vector3" then var2.Footprint else Vector3.new(1, 1, 1)
	if not var4 or (not var4:IsA("BasePart")) then
		return var6, Vector3.new(0, 0, 0)
	end

	local var7 = var3:GetPivot():ToObjectSpace(var4.CFrame)
	local var8 = var4.Size * 0.5
	local var9 = var7.Position
	return Vector3.new((math.abs(var7.XVector.X) * var8.X + math.abs(var7.YVector.X) * var8.Y + math.abs(var7.ZVector.X) * var8.Z) * 2, var6.Y, (math.abs(var7.XVector.Z) * var8.X + math.abs(var7.YVector.Z) * var8.Y + math.abs(var7.ZVector.Z) * var8.Z) * 2), (Vector3.new(var9.X, 0, var9.Z))
end

tbl3.GetPreviewModel = function(arg1)
	if not tbl3.Get(arg1) or (not var2:IsClient()) then
		return nil
	end

	local var3 = var1.LocalPlayer
	local var4 = var3
	var4 = var4 and var3:FindFirstChildOfClass("PlayerGui")
	local var5 = var4
	var5 = var5 and var4:FindFirstChild("ItemPreviews")
	local var6 = var5
	var6 = var6 and var5:FindFirstChild(arg1)
	if var6 and var6:IsA("Model") then
		return var6
	end

	return nil
end

return tbl3

