		end
	end

	for k3, v3 in arg2.Actors, nil do
		local var7 = nil
		local var8
		if v3.Unit then
			var7 = var1.GetModelInfo(v3.Unit)
			if not var7 then
				local str3 = "PlotSceneConfig: %s.%s uses unknown unit %s"
				local var11 = arg1
				local var12 = v3.Id
				var8 = v3.Unit
				warn(string.format(str3, var11, var12, var8))
			end
		else
			if not var2.Get(v3.Vehicle) then
				local str4 = "PlotSceneConfig: %s.%s uses unknown vehicle %s"
				local var13 = arg1
				local var14 = v3.Id
				var8 = tostring(v3.Vehicle)
				warn(string.format(str4, var13, var14, var8))
			end
		end

		local var15 = var7
		var15 = var15 and var7.Animations
		for k4, v4 in v3.Steps, nil do
			if v4.Kind == "WaitFor" and (not tbl1[v4.Name]) then
				local str6 = "PlotSceneConfig: %s.%s waits for %s but nothing sends it"
				local var19 = arg1
				local var20 = v3.Id
				local var21 = v4.Name
				warn(string.format(str6, var19, var20, var21))
			end

			local var22 = v4.Anim
			var22 = var22 or v4.Idle
			if not var22 or (not var15) then
				continue
			end

			if var15[var22] then
				continue
			end

			local str7 = "PlotSceneConfig: %s.%s plays unknown animation %s"
			local var23 = arg1
			local var24 = v3.Id
			local var25 = var22
			warn(string.format(str7, var23, var24, var25))
		end
	end
end

